import React, { useState } from 'react';

const scenarios = [
  {
    task: 'Choose the typography, colors, spacing, and visual style for a checkout screen.',
    answer: 'Design',
    explanation: 'This is primarily a visual and experience-design decision.'
  },
  {
    task: 'Build the checkout form, validate fields, handle loading states, and update the interface when the user submits it.',
    answer: 'Frontend',
    explanation: 'This is browser-facing interface implementation and behavior.'
  },
  {
    task: 'Store the order in a database after the checkout request is received.',
    answer: 'Backend',
    explanation: 'Persistent server-side data handling belongs behind the interface.'
  }
];

export default function FrontendDetective() {
  const [index, setIndex] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const scenario = scenarios[index];

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <p style={{ color: '#8b949e', marginTop: 0 }}>
        Which role is primarily responsible?
      </p>

      <div style={{
        padding: 16,
        background: '#161b22',
        border: '1px solid #30363d',
        borderRadius: 8,
        marginBottom: 12
      }}>
        <strong>{scenario.task}</strong>
      </div>

      {revealed && (
        <div style={{
          padding: 12,
          background: '#161b22',
          borderRadius: 8,
          marginBottom: 12
        }}>
          <strong>{scenario.answer}</strong>
          <p style={{ color: '#8b949e', marginBottom: 0 }}>
            {scenario.explanation}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', gap: 8 }}>
        <button onClick={() => setRevealed(true)}>
          Reveal Answer
        </button>
        <button
          onClick={() => {
            setIndex((value) => (value + 1) % scenarios.length);
            setRevealed(false);
          }}
        >
          Next Scenario
        </button>
      </div>
    </div>
  );
}

