    explanation: 'A self-contained piece of content is a natural use for article.'
  },
  {
    prompt: 'A thematic group of content with its own heading.',
    answer: '<section>',
    explanation: 'section groups related content into a meaningful thematic part of a document.'
  }
];

export default function SemanticDetective() {
  const [index, setIndex] = useState(0);
  const [revealed, setRevealed] = useState(false);
