  display: grid;
  grid-template-columns: 1fr;
}

@media (min-width: 320px) {
  .cards {
    grid-template-columns: repeat(3, 1fr);
  }
}

img {
  max-width: 100%;
  height: auto;
}

.content {
  width: min(100% - 32px, 720px);
  margin-inline: auto;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, sans-serif;
  color: #111827;
  background: #f8fafc;
}

a {
  color: inherit;
}

.app-shell {
  width: min(100% - 32px, 1200px);
  margin-inline: auto;
}

.eyebrow {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.intro h1 {
  font-size: clamp(2rem, 5vw, 4rem);
  line-height: 1.05;
  margin-bottom: 16px;
}

.lead {
  max-width: 65ch;
  line-height: 1.6;
}

.lesson-card {
  padding: 24px;
  background: white;
  border: 1px solid #d1d5db;
  border-radius: 12px;
}

.page-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

.lessons {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.site-nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

@media (min-width: 768px) {
  .page-layout {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .lessons {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured {
    grid-column: span 2;
  }

  .site-nav {
    flex-direction: row;
  }
}

.content {
  max-width: 1400px;
}

.lesson-card {
  height: 180px;
}

@media (min-width: 320px) {
  .lessons {
    grid-template-columns: repeat(3, 1fr);
  }
}

