import React, { useState } from 'react';

export default function AutoFitExplorer() {
  const [mode, setMode] = useState('auto-fit');
  const [items, setItems] = useState(4);

  const cards = Array.from({ length: items }, (_, index) => `Card ${index + 1}`);

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <p style={{ color: '#8b949e' }}>
        repeat({mode}, minmax(180px, 1fr))
      </p>

      <div style={{
        display: 'grid',
        gridTemplateColumns: `repeat(${mode}, minmax(180px, 1fr))`,
        gap: 12,
        padding: 16,
        background: '#161b22',
        borderRadius: 8,
        border: '1px solid #30363d'
      }}>
        {cards.map((card) => (
          <div
            key={card}
            style={{
              padding: 20,
              background: '#1f2937',
              borderRadius: 8,
              border: '1px solid #30363d'
            }}
          >
            {card}
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 12 }}>
        <button onClick={() => setMode((value) => value === 'auto-fit' ? 'auto-fill' : 'auto-fit')}>
          Toggle mode
        </button>
        <button onClick={() => setItems((value) => value === 4 ? 2 : 4)}>
          Toggle item count
        </button>
      </div>
    </div>
  );
}

