import React, { useState } from 'react';

export default function TransitionPlayground() {
  const [duration, setDuration] = useState(180);
  const [timing, setTiming] = useState('ease-out');

  return (
    <div style={{
      padding: 32,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif',
      textAlign: 'center'
    }}>
      <button
        style={{
          padding: '12px 20px',
          border: 0,
          borderRadius: 8,
          background: '#2563eb',
          color: 'white',
          transition: `transform ${duration}ms ${timing}, opacity ${duration}ms ${timing}`
        }}
        onMouseEnter={(event) => {
          event.currentTarget.style.transform = 'translateY(-4px)';
          event.currentTarget.style.opacity = '0.88';
        }}
        onMouseLeave={(event) => {
          event.currentTarget.style.transform = 'translateY(0)';
          event.currentTarget.style.opacity = '1';
        }}
      >
        Hover me
      </button>

      <div style={{ display: 'flex', gap: 8, justifyContent: 'center', marginTop: 20 }}>
        <button onClick={() => setDuration((value) => value === 180 ? 500 : 180)}>
          Toggle duration
        </button>
        <button onClick={() => setTiming((value) => value === 'ease-out' ? 'linear' : 'ease-out')}>
          Toggle timing
        </button>
      </div>
    </div>
  );
}

