import React, { useMemo, useState } from 'react';

export default function ArrayMethodsLab() {
  const [completedThreshold, setCompletedThreshold] = useState(70);
  const [searchTitle, setSearchTitle] = useState('JavaScript');

  const lessons = [
    { title: 'HTML', score: 80, completed: true },
    { title: 'CSS', score: 65, completed: false },
    { title: 'JavaScript', score: 92, completed: true },
    { title: 'Testing', score: 74, completed: false }
  ];

  const labels = useMemo(() => {
    return lessons.map((lesson) => `${lesson.title}: ${lesson.score}%`);
  }, []);

  const completed = lessons.filter((lesson) => lesson.completed);

  const totalScore = lessons.reduce((sum, lesson) => {
    return sum + lesson.score;
  }, 0);

  const matchingLesson = lessons.find((lesson) => {
    return lesson.title === searchTitle;
  });

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
        <button onClick={() => setCompletedThreshold((value) => value === 70 ? 90 : 70)}>
          Change score threshold
        </button>
        <button onClick={() => setSearchTitle((value) => value === 'JavaScript' ? 'CSS' : 'JavaScript')}>
          Change searched lesson
        </button>
      </div>

      <p style={{ color: '#8b949e' }}>
        Watch how each method produces a different shape of result.
      </p>

      <pre style={{ whiteSpace: 'pre-wrap' }}>
        {JSON.stringify({
          labels,
          completed,
          totalScore,
          matchingLesson,
          threshold: completedThreshold
        }, null, 2)}
      </pre>
    </div>
  );
}

