export default function LessonStatesPlayground() {
  const [status, setStatus] = useState('loading');
  const [lessons, setLessons] = useState([]);
  const [error, setError] = useState(null);

  function simulateLoading() {
    setStatus('loading');
    setLessons([]);
    setError(null);
  }

  function simulateSuccessWithData() {
    setStatus('success');
    setLessons([
      { id: 1, title: 'Loading States' },
      { id: 2, title: 'Error States' }
    ]);
    setError(null);
  }

  function simulateEmpty() {
    setStatus('success');
    setLessons([]);
    setError(null);
  }

  function simulateError() {
    setStatus('error');
    setLessons([]);
    setError('Lesson service is unavailable.');
  }

  function renderContent() {
    if (status === 'loading') {
      return <p>Loading lessons…</p>;
    }

    if (status === 'error') {
      return (
        <div>
          <p>{error}</p>
          <button onClick={simulateLoading}>Try again</button>
        </div>
      );
    }

    if (lessons.length === 0) {
      return <p>No lessons to display yet.</p>;
    }

    return (
      <ul>
        {lessons.map((lesson) => (
          <li key={lesson.id}>{lesson.title}</li>
        ))}
      </ul>
    );
  }

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
        <button onClick={simulateLoading}>Loading</button>
        <button onClick={simulateSuccessWithData}>Success</button>
