import React, { useState } from 'react';

export default function FetchPlayground() {
  const [endpoint, setEndpoint] = useState('/api/lessons');
  const [status, setStatus] = useState('idle');
  const [message, setMessage] = useState('Ready');

  async function load() {
    setStatus('loading');
    setMessage('Loading…');

    try {
      const response = await fetch(endpoint);

      setMessage(`HTTP ${response.status} — ok: ${response.ok}`);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();

      if (Array.isArray(data) && data.length === 0) {
        setStatus('empty');
        setMessage('Request succeeded, but there is no data.');
        return;
      }

      setStatus('success');
      setMessage(`Loaded ${Array.isArray(data) ? data.length : 1} result(s).`);
    } catch (error) {
      setStatus('error');
      setMessage(`Could not load data: ${error.message}`);
    }
  }

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <label>
        Endpoint
        <input
          value={endpoint}
          onChange={(event) => setEndpoint(event.target.value)}
          style={{ marginLeft: 8, minWidth: 280 }}
        />
      </label>

      <button onClick={load} style={{ marginLeft: 8 }}>
        Fetch
      </button>

      <p>Status: {status}</p>
      <p>{message}</p>
    </div>
  );
}

