    event.preventDefault();

    const nextQuery = query.trim();

    if (!nextQuery) {
      setError('Enter a search term.');
      setStatus('idle');
      return;
    }

    setError(null);
    setSubmittedQuery(nextQuery);
  }

  useEffect(() => {
    if (!submittedQuery) {
      return;
    }

    let ignore = false;

    async function search() {
      setStatus('loading');
      setError(null);

      try {
        const response = await fetch(
          `/api/lessons?search=${encodeURIComponent(submittedQuery)}`
        );

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();

        if (ignore) {
          return;
        }

        setResults(data);
        setStatus('success');
      } catch (error) {
        if (ignore) {
          return;
        }

        setResults([]);
        setError(error.message);
        setStatus('error');
      }
    }

    search();

    return () => {
      ignore = true;
